pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        // fund the test contract and deposit into c via its payable fallback
        vm.deal(address(this), amount);
        (bool s, ) = address(c).call{value: amount}("");
        assertTrue(s);
        // adversarial caller: a contract whose receive/fallback always reverts,
        // so c's transfer() to it fails inside withdraw
        Reverter r = new Reverter();
        vm.prank(address(r));
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        // Reference: withdrawAll always reverts when the owner cannot receive ETH.
        // Mutant: withdrawAll does nothing and succeeds.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}

