pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seedBalance, uint256 amount) public {
        // give the contract some balance, wide domain
        seedBalance = bound(seedBalance, 1 ether, 100 ether);
        // pick a withdrawal amount strictly below the balance (admissible for P)
        amount = bound(amount, 0, seedBalance - 1);

        // fund the contract via fallback (deal to owner then send)
        address funder = address(0xBEEF);
        vm.deal(funder, seedBalance);
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: seedBalance}("");
        assertTrue(sent);

        uint256 before = address(c).balance;
        address owner = c.owner();

        vm.prank(owner);
        c.withdraw(amount);

        // Rule: withdrawing `amount` must leave exactly balance - amount.
        assertTrue(
            address(c).balance == before - amount,
            "withdraw(amount) must deduct exactly amount"
        );
    }
}

